        epoch, fault, active = row
        if not isinstance(epoch, (int, float)):
            raise ValueError(f"Row {i} epoch must be int or float")
        if isinstance(epoch, bool):
            raise ValueError(f"Row {i} epoch cannot be bool")
        if not isinstance(fault, (bool, type(None))):
            raise ValueError(f"Row {i} fault must be bool or None")
        if isinstance(fault, bool):
            raise ValueError(f"Row {i} fault cannot be bool")
        if not isinstance(active, (bool, type(None))):
            raise ValueError(f"Row {i} active must be bool or None")
        if isinstance(active, bool):
            raise ValueError(f"Row {i} active cannot be bool")

        if i > 0:
            prev_epoch = samples[i-1][0]
            if epoch == prev_epoch:
                raise ValueError(f"Duplicate epoch at index {i}")

    sorted_samples = sorted(samples, key=lambda x: x[0])

    fault_hours = 0.0
    covered_hours = 0.0

    for i in range(len(sorted_samples)):
        epoch = sorted_samples[i][0]
        fault = sorted_samples[i][1]
        active = sorted_samples[i][2]

        if i == len(sorted_samples) - 1:
            next_epoch = epoch + max_gap_s
        else:
            next_epoch = sorted_samples[i+1][0]

        duration = min(next_epoch - epoch, max_gap_s)

        if active and fault is True:
            fault_hours += duration
            covered_hours += duration

    return (fault_hours / 3600.0, covered_hours / 3600.0)"}

