        current_epoch = unique_epochs[i]
        next_epoch = unique_epochs[i+1] if i+1 < len(unique_epochs) else current_epoch + max_gap_s
        duration = min(next_epoch - current_epoch, max_gap_s)

        if i == len(unique_epochs) - 1:
            row = samples[-1]
        else:
            row = samples[i]

        if row[2] is True and row[1] is True:
            fault_hours += duration
            covered_hours += duration

    return (fault_hours / 3600.0, covered_hours / 3600.0)"
