  "source": "import math

def fault_hours(samples, max_gap_s):
    if not isinstance(samples, list):
        raise ValueError("samples must be a list")
    if not isinstance(max_gap_s, (int, float)) or max_gap_s <= 0:
        raise ValueError("max_gap_s must be a positive number")

    if len(samples) == 0:
        return (0.0, 0.0)

    # Validate and process samples
    processed = {}
    for i, row in enumerate(samples):
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            raise ValueError("Each row must be a list or tuple of length 3")

        epoch, fault, active = row

        if not isinstance(epoch, (int, float)) or not math.isfinite(epoch):
            raise ValueError("epoch must be a finite number")

        if not isinstance(fault, (bool, type(None))):
            raise ValueError("fault must be a bool or None")

        if not isinstance(active, (bool, type(None))):
            raise ValueError("active must be a bool or None")

        if epoch in processed:
            raise ValueError("Duplicate epochs are not allowed")

        processed[epoch] = (fault, active)

    # Sort epochs
    epochs = sorted(processed.keys())

    if len(epochs) <= 1:
        return (0.0, 0.0)

    total_fault_seconds = 0.0
    total_covered_seconds = 0.0

    for i in range(len(epochs) - 1):
        current_epoch = epochs[i]
        next_epoch = epochs[i + 1]

        fault, active = processed[current_epoch]

        # Calculate interval duration
        duration = min(next_epoch - current_epoch, max_gap_s)

        # Only count if active and fault is a bool
        if active is True and fault is not None:
            total_covered_seconds += duration
            if fault is True:
                total_fault_seconds += duration

    return (total_fault_seconds / 3600.0, total_covered_seconds / 3600.0)"
}

